for lang in ("el", "es"):
    ids = [g["id"] for g in en["glossary"]]
    assert set(G[lang]) == set(ids), set(ids) ^ set(G[lang])
    assert set(L[lang]) == set(en["diagramLabels"]), set(en["diagramLabels"]) ^ set(L[lang])
    meta = {"language": lang,
            "glossary": [{"id": i, "term": G[lang][i][0], "definition": G[lang][i][1]} for i in ids],
            "diagramLabels": {k: L[lang][k] for k in en["diagramLabels"]}}
    d = ROOT / "content-src" / lang
    d.mkdir(parents=True, exist_ok=True)
    (d / "_meta.json").write_text(json.dumps(meta, ensure_ascii=False, indent=2) + "\n")
    print(lang, "meta written:", len(ids), "terms,", len(meta["diagramLabels"]), "labels")
